<script setup>
import {counted} from '../api/pluralRu'
import { computed, ref } from 'vue'
import Button from '../components/ui/Button.vue'
import Card from '../components/ui/Card.vue'
import PageState from '../components/ui/PageState.vue'
import SvgIcon from '../components/ui/SvgIcon.vue'
import StatusBadge from '../components/ui/StatusBadge.vue'
import DeviceArt from '../components/illustrations/DeviceArt.vue'
import ClientRequestDetails from '../components/ClientRequestDetails.vue'
import { useClientRequests } from '../composables/useClientRequests'
import { useMockPage } from '../composables/useMockPage'
import { useNotifications } from '../composables/useNotifications'
import { useSession } from '../composables/useSession'
import { servicesView } from '../data/services'
import { clientServiceMedia } from '../data/clientServiceMedia'
import { servicePoints } from '../data/servicePoints'
import { requestPhase, requestPhases, requestHints } from '../data/clientWorkspace'
import requestPhoto from '../assets/Гость/Как_мы_работаем/Заявка.jpg'
import visitPhoto from '../assets/Клиент/Выезд_мастера.jpg'
import servicePhoto from '../assets/Гость/Как_мы_работаем/Диагностика.jpg'
const { current } = useSession()
const { requests, loading, error, stats, load } = useClientRequests()
const page = useMockPage()
const { notifications, unreadCount } = useNotifications()
const selected = ref(null)
const list = computed(() => page.empty.value ? [] : requests.value)
const active = computed(() => list.value.filter(r => ['new','confirmed','assigned','in_progress','waiting_parts','ready_for_pickup'].includes(r.status)))
const ready = computed(() => list.value.filter(r => r.status === 'ready_for_pickup'))
const metrics = computed(() => [
 { label: 'Всего заявок', value: list.value.length, note: 'История ваших обращений', icon: 'clipboard', tone: 'blue', to: '/client/requests?status=all' },
 { label: 'Активные', value: active.value.length, note: 'От обращения до выдачи', icon: 'wrench', tone: 'amber', to: '/client/requests?active=1' },
 { label: 'Завершено', value: list.value.filter(r => ['completed','closed'].includes(r.status)).length, note: 'Выполненные и закрытые', icon: 'checkCircle', tone: 'green', to: '/client/requests?done=1' },
 { label: 'Готово к выдаче', value: ready.value.length, note: 'Можно получить в сервисе', icon: 'box', tone: 'purple', to: '/client/requests?status=ready_for_pickup' },
])
const recommended = computed(()=>servicesView.slice(0,3))
function retry() { page.retry(); load() }
function selectedService(s) { return { path: '/client/requests/new', query: { service: s.name } } }
</script>
<template>
 <div class="client-home">
  <section class="client-welcome">
   <div class="welcome-photo"><img :src="requestPhoto" alt="Оформление обращения с телефона в спокойной домашней обстановке" fetchpriority="high"/></div>
   <div class="welcome-copy"><span class="client-kicker"><span></span>ВАШ ЛИЧНЫЙ СЕРВИС</span><h1>Здравствуйте,<br>{{ current.name.split(' ')[0] }}</h1><p>Техника — в надёжных руках.<br>Заявки, статусы и всё важное о ремонте — здесь.</p><div class="welcome-actions"><Button to="/client/requests/new" variant="primary" size="lg">Создать заявку<template #iconRight><SvgIcon name="plus" :size="18"/></template></Button><Button to="/client/requests" variant="outline" size="lg">Мои заявки</Button></div></div>

  </section>
  <PageState :loading="loading || page.loading.value" :error="!!error || page.error.value" @retry="retry">
   <section class="client-metrics" aria-label="Ваши заявки в цифрах"><RouterLink v-for="m in metrics" :key="m.label" :to="m.to"><Card padding="md" class="client-metric"><div class="metric-heading"><span>{{ m.label }}</span><span class="metric-icon" :class="m.tone"><SvgIcon :name="m.icon" :size="19"/></span></div><strong>{{ m.value }}</strong><p>{{ m.note }}<SvgIcon name="arrowRight" :size="14"/></p></Card></RouterLink></section>
   <RouterLink v-if="ready.length" :to="`/client/requests?request=${ready[0].id}`" class="client-ready"><span class="ready-icon"><SvgIcon name="checkCircle" :size="24"/></span><div><strong>Хорошие новости: техника готова к выдаче</strong><p>{{ ready[0].device }} · {{ ready[0].service_point ?? 'Сервисный центр' }}</p></div><span class="ready-link">Подробнее<SvgIcon name="arrowRight" :size="16"/></span></RouterLink>
   <section class="client-workspace">
    <Card padding="lg" class="client-active"><div class="client-section-head"><div><span class="client-kicker">ВСЁ ПОД КОНТРОЛЕМ</span><h2>Ваши активные заявки</h2><p>Последние обращения и ближайшие шаги</p></div><RouterLink to="/client/requests">Все заявки<SvgIcon name="arrowRight" :size="16"/></RouterLink></div>
     <div v-if="active.length" class="active-request-list"><button v-for="r in active.slice(0,3)" :key="r.id" class="active-request" @click="selected = r"><div class="active-request-main"><span class="active-device"><DeviceArt :name="r.icon"/></span><div class="active-request-info"><span class="request-code">{{ r.request_number }}</span><h3>{{ r.device }}</h3><p>{{ r.description }}</p></div><SvgIcon name="chevronRight" :size="18" class="text-muted"/></div><div class="active-request-status"><StatusBadge :status="r.status"/><span>{{ r.service_mode === 'onsite' ? 'Выезд мастера' : 'В сервисе' }}</span></div><div class="client-progress" aria-hidden="true"><span v-for="(phase,i) in requestPhases" :key="phase" :class="{ reached: i <= requestPhase(r.status) }"><i></i><small>{{ phase }}</small></span></div><p class="active-next"><SvgIcon :name="r.status === 'waiting_parts' ? 'box' : 'infoCircle'" :size="14"/>{{ requestHints[r.status] }}</p></button></div>
     <div v-else class="client-empty"><span><DeviceArt name="laptop"/></span><h3>Пока всё спокойно</h3><p>Активных заявок нет. Если техника подведёт — мы рядом.</p><Button to="/client/requests/new" variant="outline">Создать первую заявку</Button></div>
    </Card>
    <aside class="client-side"><Card padding="lg" class="client-shortcuts"><span class="client-kicker">БЫСТРЫЙ ДОСТУП</span><h2>Что хотите сделать?</h2><RouterLink v-for="item in [{title:'Выбрать услугу',text:'Каталог и базовые цены',icon:'wrench',to:'/client/services'},{title:'Проверить уведомления',text:'Изменения по вашим заявкам',icon:'bell',to:'/client/notifications'},{title:'Обновить профиль',text:'Ваши контактные данные',icon:'user',to:'/client/profile'}]" :key="item.title" :to="item.to"><span><SvgIcon :name="item.icon" :size="19"/></span><div><strong>{{ item.title }}</strong><small>{{ item.text }}</small></div><SvgIcon name="chevronRight" :size="16"/></RouterLink></Card>
     <Card padding="lg" class="client-feed"><div class="client-section-head"><h2>Последние события</h2><SvgIcon name="bell" :size="18" class="text-brand"/></div><RouterLink v-for="n in notifications.slice(0,3)" :key="n.id" to="/client/notifications"><span class="feed-dot" :class="{ unread: n.unread }"></span><div><strong>{{ n.title }}</strong><p>{{ n.text }}</p><small>{{ n.time }}</small></div></RouterLink><RouterLink class="feed-all" to="/client/notifications">Все уведомления<SvgIcon name="arrowRight" :size="15"/></RouterLink></Card>
    </aside>
   </section>
  </PageState>
  <section><div class="client-section-head section-top"><div><span class="client-kicker">ПОМОЖЕМ С ТЕХНИКОЙ</span><h2>Часто выбирают</h2><p>Понятные услуги с базовой стоимостью</p></div><RouterLink to="/client/services">Весь каталог<SvgIcon name="arrowRight" :size="16"/></RouterLink></div><div class="client-services-preview"><Card v-for="s in recommended" :key="s.id" padding="none" class="client-service-photo"><RouterLink :to="selectedService(s)" :aria-label="`Выбрать: ${s.name}`"><div class="service-preview-image"><img :src="s.image" :alt="s.name" loading="lazy"/><span>{{ s.category }}</span></div><div class="service-preview-copy"><h3>{{ s.name }}</h3><p>{{ s.description }}</p><div><strong>{{ s.price }}</strong><span><SvgIcon name="arrowRight" :size="18"/></span></div></div></RouterLink></Card></div><p class="client-price-note"><SvgIcon name="infoCircle" :size="14"/>Итоговая стоимость зависит от диагностики, работ и необходимых деталей.</p></section>
  <section><div class="client-section-head section-top"><div><span class="client-kicker">КАК ВАМ УДОБНЕЕ</span><h2>Два формата заботы о технике</h2></div></div><div class="client-format-grid"><RouterLink v-for="f in [{mode:'onsite',title:'Мастер приедет к вам',text:'Укажите адрес и желаемое время. Учтём район и доступность специалиста.',image:visitPhoto,icon:'home'},{mode:'dropoff',title:'Привезите технику в сервис',text:'Выберите точку приёма. О готовности сообщим в личном кабинете.',image:servicePhoto,icon:'store'}]" :key="f.mode" :to="{ path:'/client/requests/new',query:{mode:f.mode} }" class="client-format"><img :src="f.image" :alt="f.title" loading="lazy"/><div><span><SvgIcon :name="f.icon" :size="21"/></span><h3>{{ f.title }}</h3><p>{{ f.text }}</p><strong>Создать заявку<SvgIcon name="arrowRight" :size="16"/></strong></div></RouterLink></div></section>
  <Card padding="md" class="client-support"><span><SvgIcon name="phone" :size="21"/></span><div><strong>Нужна помощь с обращением?</strong><p>Свяжитесь с сервисом — уточним детали вместе.</p></div><a :href="`tel:${(servicePoints[0]?.phone??'+7 800 123-45-67').replace(/[^+\d]/g,'')}`">{{ (servicePoints[0]?.phone??'+7 800 123-45-67') }}<SvgIcon name="arrowRight" :size="16"/></a></Card>
  <ClientRequestDetails :request="selected" @close="selected = null" @changed="load"/>
 </div>
</template>
